		return "", fmt.Errorf("unsafe repository name %q for candidate checkout", repo)
	}
	root, err := filepath.Abs(home)
	if err != nil {
		return "", err
	}
	if resolved, err := filepath.EvalSymlinks(root); err == nil {
		root = resolved
	} else if !os.IsNotExist(err) {
		return "", err
	}
