// requests Review of unpromoted private candidates, as a single-repository
// done Signal from an active candidate does. Candidates a Review already
// covers are past the request and face the publication barrier instead.
// Every changed lane then needs a submitted candidate, and each active one a
// clean checkout.
func (s *Service) workspaceCandidateReviewRequest(ctx context.Context, db *store.DB, home string, project store.Project, task store.Task, lanes []candidateLane) (bool, error) {
	request := false
	for _, lane := range lanes {
		candidate, err := db.LatestValidationCandidate(ctx, task.ID, lane.repo)
		if err != nil && !store.IsNotFound(err) {
			return false, err
		}
		if err == nil && candidate.State == store.ValidationCandidateActive {
			request = true
		}
	}
	if !request {
		return false, nil
	}
	targets, err := changeCandidateTargets(ctx, db, project, task)
	if err != nil {
		return false, err
	}
	if evidence, err := db.ReviewEvidenceFor(ctx, task.ID, targets); err != nil || evidence.Complete {
		return false, err
	}
	for _, lane := range lanes {
		if lane.member.State == store.TaskRepoMerged {
			continue
		}
		candidate, err := requireSubmittedCandidate(ctx, db, task, lane)
		if err != nil {
			return false, err
		}
		if candidate.State != store.ValidationCandidateActive {
			continue
		}
		if err := s.ensureCandidateCheckout(ctx, db, home, lane.task, candidate); err != nil {
			return false, err
		}
		status, err := gitStatusOutput(ctx, candidate.WorktreePath, "--porcelain", "--untracked-files=all")
		if err != nil {
			return false, err
		}
		if status != "" {
			return false, axi.Failure("candidate_dirty", lane.memberLabel("commit candidate changes before signalling done"), false, candidate.WorktreePath)
		}
	}
	return true, nil
}

// requireFullPipelineValidationAt is the publication barrier of Merge and the
// done Signal: every changed full-pipeline lane needs a promoted candidate
// that is its exact delivered head, against the target it was validated against,
// with current ordered results. commit pins a single-repository PR head; otherwise
// the Task branch tip, the head local integration would fast-forward, is
// checked; a local lane's gated head must also be the candidate, since local
// Merge fast-forwards to it. A Member already integrated under this barrier
// (recorded merged, or its PR merged at the validated head before the PR poll
// recorded it) is not rechecked, since its own integration moved its target.
func requireFullPipelineValidationAt(ctx context.Context, db *store.DB, project store.Project, cfg config.Config, task store.Task, commit, mergeCommit string) error {
	lanes, err := changedCandidateLanes(ctx, db, project, task)
	if err != nil {
		return err
	}
	validated := 0
	for _, lane := range lanes {
		if lane.member.State == store.TaskRepoMerged {
			validated++
			continue
		}
		if lane.repo == "" && !lane.localDelivery() {
			lane.mergeCommit, lane.mergeMethod = mergeCommit, defaultValue(cfg.Defaults.MergeMethod, "squash")
		}
		candidate, err := db.LatestValidationCandidate(ctx, task.ID, lane.repo)
		if err != nil {
			return axi.Failure("candidate_missing", lane.memberLabel("full-pipeline Task has no submitted private candidate"), false)
		}
		head := commit
		if commit != "" {
			candidates, err := db.ValidationCandidates(ctx, task.ID)
			if err != nil {
				return err
			}
			for _, recorded := range candidates {
				if recorded.Repo == lane.repo && recorded.PromotedSHA == commit &&
					(recorded.State == store.ValidationCandidatePromoted || recorded.State == store.ValidationCandidateSuperseded) {
					candidate = recorded
